using System.Text.Json; using Fatewake.Infrastructure.Persistence; using Fatewake.Infrastructure.Work;
namespace Fatewake.Infrastructure.Art;
/// <summary>Creates and persists the WebP delivery derivative from a durable master PNG.</summary>
/// <remarks><see href="../../../docs/code/src/Fatewake.Infrastructure/Art/ArtEncodeWebPWorkStepHandler.md">ArtEncodeWebPWorkStepHandler documentation</see>.</remarks>
public sealed class ArtEncodeWebPWorkStepHandler(IWorkArtifactStore artifacts,IArtBinaryStorage storage,IArtImageProcessor images):IWorkStepHandler
{
 public string StepType=>ArtWorkStepTypes.EncodeWebP;
 public async Task<string?> ExecuteAsync(WorkStepExecutionContext context,CancellationToken ct){var old=await artifacts.GetAsync(context.JobId,"art.webp",ct);if(old is not null)return old;var master=JsonSerializer.Deserialize<ArtMasterArtifact>(await artifacts.GetAsync(context.JobId,"art.master",ct)??throw new InvalidOperationException("Master artifact required."))!;var resolve=JsonSerializer.Deserialize<ArtResolveResult>(await artifacts.GetAsync(context.JobId,"art.resolve",ct)??throw new InvalidOperationException("Resolve artifact required."))!;if(resolve.Reused&&!string.IsNullOrWhiteSpace(resolve.WebPStorageKey)){var info=await images.InspectAsync(await ArtWorkStepUtilities.ReadAllAsync(storage,resolve.WebPStorageKey,ct),ct);var reused=new ArtDerivativeArtifact(resolve.WebPStorageKey,"image/webp","",info.Width,info.Height,0,"approved-reuse");var reusedJson=JsonSerializer.Serialize(reused);await artifacts.PutAsync(context.JobId,"art.webp",reusedJson,ct);return reusedJson;}var bytes=await ArtWorkStepUtilities.ReadAllAsync(storage,master.StorageKey,ct);var image=await images.CreateWebPAsync(bytes,ct);var key=$"art/staging/{context.JobId:N}/delivery.webp";await using(var s=new MemoryStream(image.Bytes,false))await storage.PutAsync(key,s,image.ContentType,ct);var result=new ArtDerivativeArtifact(key,image.ContentType,ArtWorkStepUtilities.Hash(image.Bytes),image.Info.Width,image.Info.Height,image.Bytes.LongLength,image.EncoderMetadata);var json=JsonSerializer.Serialize(result);await artifacts.PutAsync(context.JobId,"art.webp",json,ct);return json;}
}